349f6272-94d8-453f-b753-b885293e6cc8	1BfRQ1UPD3	gw_service.sh	### Gateway Service Check Script \n\n[gw_service.sh 12535](/api/attachments.redirect?id=61369365-51fa-4a85-9136-ac7a0877645a)\n\n\\\n```bash\n#!/bin/bash\r\n\r\n# Color codes\r\nGREEN='\\033[0;32m'\r\nRED='\\033[0;31m'\r\nYELLOW='\\033[1;33m'\r\nBLUE='\\033[0;34m'\r\nCYAN='\\033[0;36m'\r\nNC='\\033[0m' # No Color\r\n\r\n# Log file paths\r\nGATEWAY_LOG="/var/connect/logs/connect-gw.log"\r\nVPN_LOG="/var/connect/connect-vpn/log/connect-vpn.log"\r\n\r\n# Service group definitions\r\ndeclare -A SERVICE_MAP=(\r\n    ["rsyslog"]="rsyslog.service"\r\n    ["cron"]="cron.service"\r\n    ["redis"]="redis.service"\r\n    ["gateway-check"]="connect-gateway-check.service"\r\n    ["gateway"]="connect-gateway.service"\r\n    ["nginx"]="nginx.service"\r\n    ["vpn"]="connect-vpn.service"\r\n    ["strongswan"]="strongswan-starter.service"\r\n    ["dhcp"]="isc-dhcp-server.service"\r\n    ["dhcp6"]="isc-dhcp-server6.service"\r\n    ["syn-driver"]="syn_driver.service"\r\n    ["syn-gateway"]="syn_gateway.service"\r\n)\r\n\r\n# All services list (order matters)\r\nALL_SERVICES=("rsyslog" "cron" "redis" "syn-driver" "syn-gateway" "nginx" "gateway" "gateway-check" "vpn" "strongswan" "dhcp" "dhcp6")\r\n\r\n# Utility services group\r\nUTIL_SERVICES=("rsyslog" "cron")\r\n\r\n# Redis services group\r\nREDIS_SERVICES=("redis")\r\n\r\n# Web services group\r\nWEB_SERVICES=("gateway-check" "gateway" "nginx")\r\n\r\n# VPN services group\r\nVPN_SERVICES=("vpn" "strongswan")\r\n\r\n# DHCP services group\r\nDHCP_SERVICES=("dhcp" "dhcp6")\r\n\r\n# Kernel module services group\r\nKERNEL_SERVICES=("syn-driver" "syn-gateway")\r\n\r\n# Show usage function\r\nshow_usage() {\r\n    echo ""\r\n    echo -e "${CYAN}=========================================="\r\n    echo -e "       Service Management Script"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    echo "Usage: $0 [action] [target]"\r\n    echo ""\r\n    echo "Actions:"\r\n    echo "  start     - Start services"\r\n    echo "  stop      - Stop services"\r\n    echo "  restart   - Restart services"\r\n    echo "  status    - Check service status"\r\n    echo "  enable    - Enable services (auto-start on boot)"\r\n    echo "  disable   - Disable services (no auto-start)"\r\n    echo "  reload    - Reload systemd daemon"\r\n    echo "  log       - View log files (tail -200f)"\r\n    echo ""\r\n    echo "Targets:"\r\n    echo "  all       - All services"\r\n    echo "  util      - Utility services (rsyslog, cron)"\r\n    echo "  redis     - Redis service"\r\n    echo "  web       - Web services (gateway-check, gateway, nginx)"\r\n    echo "  vpn       - VPN services (vpn, strongswan)"\r\n    echo "  dhcp      - DHCP services (dhcp, dhcp6)"\r\n    echo "  kernel    - Kernel module services (syn-driver, syn-gateway)"\r\n    echo ""\r\n    echo "Log Targets:"\r\n    echo "  gw        - Gateway log (/var/connect/logs/connect-gw.log)"\r\n    echo "  vpn       - VPN log (/var/connect/connect-vpn/log/connect-vpn.log)"\r\n    echo ""\r\n    echo "Individual services:"\r\n    echo "  rsyslog       - Rsyslog"\r\n    echo "  cron          - Cron"\r\n    echo "  gateway-check - Gateway Check service"\r\n    echo "  gateway       - Gateway service"\r\n    echo "  nginx         - Nginx"\r\n    echo "  vpn           - VPN service"\r\n    echo "  strongswan    - StrongSwan"\r\n    echo "  dhcp          - DHCP server (IPv4)"\r\n    echo "  dhcp6         - DHCP server (IPv6)"\r\n    echo "  syn-driver    - SYN Driver"\r\n    echo "  syn-gateway   - SYN Gateway"\r\n    echo ""\r\n    echo "Examples:"\r\n    echo "  sudo $0 status all          # Check all services status"\r\n    echo "  sudo $0 start web           # Start web services"\r\n    echo "  sudo $0 stop vpn            # Stop VPN services"\r\n    echo "  sudo $0 restart nginx       # Restart Nginx"\r\n    echo "  sudo $0 start dhcp          # Start DHCP services"\r\n    echo "  sudo $0 enable web          # Enable web services auto-start"\r\n    echo "  sudo $0 disable vpn         # Disable VPN services auto-start"\r\n    echo "  sudo $0 reload              # Reload systemd daemon"\r\n    echo "  sudo $0 log gw              # View gateway log"\r\n    echo "  sudo $0 log vpn             # View VPN log"\r\n    echo ""\r\n    echo -e "${CYAN}==========================================${NC}"\r\n    echo ""\r\n}\r\n\r\n# Check service status function\r\ncheck_status() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${CYAN}=========================================="\r\n    echo -e "       Service Status Check"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${services[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        if systemctl is-active --quiet "$service"; then\r\n            status="${GREEN}●${NC} active (running)"\r\n        else\r\n            status="${RED}●${NC} inactive (dead)"\r\n        fi\r\n        \r\n        if systemctl is-enabled --quiet "$service" 2>/dev/null; then\r\n            enabled="${GREEN}enabled${NC}"\r\n        else\r\n            enabled="${YELLOW}disabled${NC}"\r\n        fi\r\n        \r\n        printf "${BLUE}[%-13s]${NC} %-35s %b (%b)\\n" "$svc_name" "$service" "$status" "$enabled"\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${CYAN}==========================================${NC}"\r\n    echo ""\r\n}\r\n\r\n# Start services function\r\nstart_services() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${GREEN}=========================================="\r\n    echo -e "       Starting Services"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${services[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        echo -en "${BLUE}[${svc_name}]${NC} Starting ${service}... "\r\n        \r\n        if systemctl start "$service" 2>/dev/null; then\r\n            echo -e "${GREEN}✓ Success${NC}"\r\n        else\r\n            echo -e "${RED}✗ Failed${NC}"\r\n        fi\r\n        sleep 0.5\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${GREEN}Services started successfully!${NC}"\r\n    check_status "${services[@]}"\r\n}\r\n\r\n# Stop services function\r\nstop_services() {\r\n    local services=("$@")\r\n    local reversed=()\r\n    \r\n    # Reverse array order (considering dependencies)\r\n    for ((i=${#services[@]}-1; i>=0; i--)); do\r\n        reversed+=("${services[i]}")\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${RED}=========================================="\r\n    echo -e "       Stopping Services"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${reversed[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        echo -en "${BLUE}[${svc_name}]${NC} Stopping ${service}... "\r\n        \r\n        if systemctl stop "$service" 2>/dev/null; then\r\n            echo -e "${GREEN}✓ Success${NC}"\r\n        else\r\n            echo -e "${YELLOW}⚠ Failed (already stopped or error)${NC}"\r\n        fi\r\n        sleep 0.5\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${RED}Services stopped successfully!${NC}"\r\n    check_status "${services[@]}"\r\n}\r\n\r\n# Restart services function\r\nrestart_services() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${YELLOW}=========================================="\r\n    echo -e "       Restarting Services"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    stop_services "${services[@]}"\r\n    sleep 2\r\n    start_services "${services[@]}"\r\n}\r\n\r\n# Enable services function\r\nenable_services() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${GREEN}=========================================="\r\n    echo -e "       Enabling Services"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${services[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        echo -en "${BLUE}[${svc_name}]${NC} Enabling ${service}... "\r\n        \r\n        if systemctl enable "$service" 2>/dev/null; then\r\n            echo -e "${GREEN}✓ Success${NC}"\r\n        else\r\n            echo -e "${RED}✗ Failed${NC}"\r\n        fi\r\n        sleep 0.3\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${GREEN}Services enabled successfully!${NC}"\r\n    check_status "${services[@]}"\r\n}\r\n\r\n# Disable services function\r\ndisable_services() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${YELLOW}=========================================="\r\n    echo -e "       Disabling Services"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${services[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        echo -en "${BLUE}[${svc_name}]${NC} Disabling ${service}... "\r\n        \r\n        if systemctl disable "$service" 2>/dev/null; then\r\n            echo -e "${GREEN}✓ Success${NC}"\r\n        else\r\n            echo -e "${RED}✗ Failed${NC}"\r\n        fi\r\n        sleep 0.3\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${YELLOW}Services disabled successfully!${NC}"\r\n    check_status "${services[@]}"\r\n}\r\n\r\n# Reload systemd daemon function\r\nreload_daemon() {\r\n    echo ""\r\n    echo -e "${CYAN}=========================================="\r\n    echo -e "       Reloading Systemd Daemon"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    echo -en "${BLUE}Executing systemctl daemon-reload...${NC} "\r\n    \r\n    if systemctl daemon-reload 2>/dev/null; then\r\n        echo -e "${GREEN}✓ Success${NC}"\r\n        echo ""\r\n        echo -e "${GREEN}Systemd daemon reloaded successfully!${NC}"\r\n    else\r\n        echo -e "${RED}✗ Failed${NC}"\r\n        echo ""\r\n        echo -e "${RED}Failed to reload systemd daemon!${NC}"\r\n        exit 1\r\n    fi\r\n    \r\n    echo ""\r\n}\r\n\r\n# View log file function\r\nview_log() {\r\n    local log_target="$1"\r\n    local log_file=""\r\n    \r\n    case "$log_target" in\r\n        gw)\r\n            log_file="$GATEWAY_LOG"\r\n            ;;\r\n        vpn)\r\n            log_file="$VPN_LOG"\r\n            ;;\r\n        *)\r\n            echo ""\r\n            echo -e "${RED}Error: Unknown log target '$log_target'${NC}"\r\n            echo -e "${YELLOW}Available log targets: gw, vpn${NC}"\r\n            echo ""\r\n            exit 1\r\n            ;;\r\n    esac\r\n    \r\n    if [ ! -f "$log_file" ]; then\r\n        echo ""\r\n        echo -e "${RED}Error: Log file not found: $log_file${NC}"\r\n        echo ""\r\n        exit 1\r\n    fi\r\n    \r\n    echo ""\r\n    echo -e "${CYAN}=========================================="\r\n    echo -e "       Viewing Log: $log_file"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    echo -e "${YELLOW}Press Ctrl+C to exit${NC}"\r\n    echo ""\r\n    \r\n    tail -200f "$log_file"\r\n}\r\n\r\n# Get target services function\r\nget_target_services() {\r\n    local target="$1"\r\n    \r\n    case "$target" in\r\n        all)\r\n            echo "${ALL_SERVICES[@]}"\r\n            ;;\r\n        util)\r\n            echo "${UTIL_SERVICES[@]}"\r\n            ;;\r\n        redis)\r\n            echo "${REDIS_SERVICES[@]}"\r\n            ;;\r\n        web)\r\n            echo "${WEB_SERVICES[@]}"\r\n            ;;\r\n        vpn)\r\n            echo "${VPN_SERVICES[@]}"\r\n            ;;\r\n        dhcp)\r\n            echo "${DHCP_SERVICES[@]}"\r\n            ;;\r\n        kernel)\r\n            echo "${KERNEL_SERVICES[@]}"\r\n            ;;\r\n        rsyslog|cron|gateway-check|gateway|nginx|strongswan|dhcp6|syn-driver|syn-gateway)\r\n            echo "$target"\r\n            ;;\r\n        *)\r\n            echo ""\r\n            return 1\r\n            ;;\r\n    esac\r\n    return 0\r\n}\r\n\r\n# Check arguments\r\nif [ $# -eq 0 ]; then\r\n    show_usage\r\n    exit 1\r\nfi\r\n\r\n# Handle help option (can be first or second argument)\r\nif [ "$1" == "help" ] || [ "$1" == "--help" ] || [ "$1" == "-h" ] || [ "$2" == "help" ] || [ "$2" == "--help" ] || [ "$2" == "-h" ]; then\r\n    show_usage\r\n    exit 0\r\nfi\r\n\r\n# Handle reload action (doesn't require target)\r\nif [ "$1" == "reload" ]; then\r\n    reload_daemon\r\n    exit 0\r\nfi\r\n\r\n# Handle log action (requires log target)\r\nif [ "$1" == "log" ]; then\r\n    if [ $# -lt 2 ]; then\r\n        echo ""\r\n        echo -e "${RED}Error: Log target must be specified.${NC}"\r\n        echo -e "${YELLOW}Available log targets: gw, vpn${NC}"\r\n        echo ""\r\n        exit 1\r\n    fi\r\n    view_log "$2"\r\n    exit 0\r\nfi\r\n\r\nif [ $# -lt 2 ]; then\r\n    echo ""\r\n    echo -e "${RED}Error: Both action and target must be specified.${NC}"\r\n    show_usage\r\n    exit 1\r\nfi\r\n\r\nACTION="$1"\r\nTARGET="$2"\r\n\r\n# Get target services\r\nTARGET_SERVICES=($(get_target_services "$TARGET"))\r\n\r\nif [ ${#TARGET_SERVICES[@]} -eq 0 ]; then\r\n    echo ""\r\n    echo -e "${RED}Error: Unknown target '$TARGET'${NC}"\r\n    show_usage\r\n    exit 1\r\nfi\r\n\r\n# Process action\r\ncase "$ACTION" in\r\n    status)\r\n        check_status "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    start)\r\n        start_services "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    stop)\r\n        stop_services "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    restart)\r\n        restart_services "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    enable)\r\n        enable_services "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    disable)\r\n        disable_services "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    *)\r\n        echo ""\r\n        echo -e "${RED}Error: Unknown action '$ACTION'${NC}"\r\n        show_usage\r\n        exit 1\r\n        ;;\r\nesac\r\n\r\nexit 0\n```\n\n\\\n\\\n	2026-02-27 01:32:35.174+00	2026-03-23 05:33:50.272+00	8950f151-a83b-4c35-a061-cee0bc45d06c	e4e3b31f-640c-4d68-b73e-59ddb0785bc5	09e7519e-eceb-43a8-a5eb-0dc9ee598c83	97bb95f8-3ffa-44aa-b51b-dfd5430f3524	4	'-1':632B '-13':524B '-200':238B,1045B '-35':527B '-51':12B '/api/attachments.redirect':9B '/bin/bash':19B '/dev/null':510B,587B,677B,779B,850B,912B '/var/connect/connect-vpn/log/connect-vpn.log':55B,302B '/var/connect/logs/connect-gw.log':52B,297B '0':24B,28B,36B,40B,187B,361B,370B,378B,386B,393B,401B,412B,423B,430B,438B,634B,1112B,1117B,1150B,1166B,1210B,1251B,1317B '0.3':794B,865B '0.5':602B,696B '033':23B,27B,31B,35B,39B,43B '0m':44B '1':32B,945B,957B,997B,1018B,1058B,1109B,1122B,1134B,1136B,1138B,1160B,1175B,1204B,1232B,1235B,1265B,1314B '12535':8B '2':509B,586B,676B,732B,778B,849B,911B,1140B,1142B,1144B,1180B,1208B,1214B,1237B '31m':29B '32m':25B '33m':33B '34m':37B '36m':41B '4a85':15B '61369365':11B '9136':16B 'ac7a0877645a':17B 'action':188B,192B,1154B,1170B,1222B,1234B,1268B,1270B,1308B,1309B 'activ':486B,493B 'alreadi':689B 'argument':1114B,1132B 'array':625B 'auto':215B,225B,408B,419B 'auto-start':214B,224B,407B,418B 'avail':989B,1196B 'b':529B,530B 'bash':18B 'blue':34B,523B,576B,666B,768B,839B,899B 'boot':218B 'c':1039B 'case':961B,1059B,1269B 'check':5B,71B,113B,138B,207B,263B,316B,318B,364B,450B,454B,466B,612B,706B,804B,875B,1094B,1113B,1273B 'code':21B 'color':20B,46B 'connect-gateway-check.service':72B 'connect-gateway.service':74B 'connect-vpn.service':78B 'consid':627B 'cron':65B,101B,124B,252B,311B,312B,1091B 'cron.service':66B 'ctrl':1038B 'cyan':38B,175B,447B,461B,541B,887B,1023B 'daemon':231B,427B,880B,883B,892B,903B,909B,924B,942B,1164B 'daemon-reload':902B,908B 'dead':500B 'declar':59B 'definit':58B 'depend':628B 'dhcp':81B,116B,148B,151B,153B,273B,274B,276B,335B,336B,341B,395B,397B,1082B,1084B 'dhcp6':83B,117B,154B,277B,340B,1098B