d6a3df91-bbdc-432f-bfba-b4703fdcb3ba	gw_service.sh	```bash\n#!/bin/bash\r\n\r\n# Color codes\r\nGREEN='\\033[0;32m'\r\nRED='\\033[0;31m'\r\nYELLOW='\\033[1;33m'\r\nBLUE='\\033[0;34m'\r\nCYAN='\\033[0;36m'\r\nNC='\\033[0m' # No Color\r\n\r\n# Log file paths\r\nWEB_LOG="/opt/connect/logs/pribit-web.log"\r\nCTRL_LOG="/opt/connect/logs/pribit-ctrl.log"\r\n\r\n# Service group definitions\r\ndeclare -A SERVICE_MAP=(\r\n    ["nginx"]="nginx"\r\n    ["rpc"]="connect-controller.service"\r\n    ["api"]="connect-controller-api.service"\r\n    ["web"]="connect-controller-web.service"\r\n    ["check"]="connect-controller-check.service"\r\n    ["redis"]="redis-server.service"\r\n    ["mariadb"]="mariadb.service"\r\n)\r\n\r\n# All services list (order matters)\r\nALL_SERVICES=("mariadb" "redis" "nginx" "rpc" "api" "web" "check")\r\n\r\n# Web services group\r\nWEB_SERVICES=("nginx" "rpc" "api" "web" "check")\r\n\r\n# Database services group\r\nDB_SERVICES=("mariadb" "redis")\r\n\r\n# Show usage function\r\nshow_usage() {\r\n    echo ""\r\n    echo -e "${CYAN}=========================================="\r\n    echo -e "       Service Management Script"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    echo "Usage: $0 [action] [target]"\r\n    echo ""\r\n    echo "Actions:"\r\n    echo "  start     - Start services"\r\n    echo "  stop      - Stop services"\r\n    echo "  restart   - Restart services"\r\n    echo "  status    - Check service status"\r\n    echo "  enable    - Enable services (auto-start on boot)"\r\n    echo "  disable   - Disable services (no auto-start)"\r\n    echo "  reload    - Reload systemd daemon"\r\n    echo "  log       - View log files (tail -200f)"\r\n    echo ""\r\n    echo "Targets:"\r\n    echo "  all       - All services"\r\n    echo "  services  - Web services (nginx, rpc, api, web, check)"\r\n    echo "  db        - Database services (mariadb, redis)"\r\n    echo "  nginx     - Nginx"\r\n    echo "  rpc       - RPC service"\r\n    echo "  api       - API service"\r\n    echo "  web       - Web service"\r\n    echo "  check     - Check service"\r\n    echo "  redis     - Redis"\r\n    echo "  mariadb   - MariaDB"\r\n    echo ""\r\n    echo "Log Targets:"\r\n    echo "  web       - Web log (/opt/connect/logs/pribit-web.log)"\r\n    echo "  ctrl      - Controller log (/opt/connect/logs/pribit-ctrl.log)"\r\n    echo ""\r\n    echo "Examples:"\r\n    echo "  sudo $0 status all          # Check all services status"\r\n    echo "  sudo $0 start services      # Start web services"\r\n    echo "  sudo $0 stop db             # Stop database services"\r\n    echo "  sudo $0 restart nginx       # Restart Nginx"\r\n    echo "  sudo $0 start mariadb       # Start MariaDB only"\r\n    echo "  sudo $0 enable web          # Enable web services auto-start"\r\n    echo "  sudo $0 disable db          # Disable database services auto-start"\r\n    echo "  sudo $0 reload              # Reload systemd daemon"\r\n    echo "  sudo $0 log web             # View web log"\r\n    echo "  sudo $0 log ctrl            # View controller log"\r\n    echo ""\r\n    echo -e "${CYAN}==========================================${NC}"\r\n    echo ""\r\n}\r\n\r\n# Check service status function\r\ncheck_status() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${CYAN}=========================================="\r\n    echo -e "       Service Status Check"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${services[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        if systemctl is-active --quiet "$service"; then\r\n            status="${GREEN}●${NC} active (running)"\r\n        else\r\n            status="${RED}●${NC} inactive (dead)"\r\n        fi\r\n        \r\n        if systemctl is-enabled --quiet "$service" 2>/dev/null; then\r\n            enabled="${GREEN}enabled${NC}"\r\n        else\r\n            enabled="${YELLOW}disabled${NC}"\r\n        fi\r\n        \r\n        printf "${BLUE}[%-8s]${NC} %-35s %b (%b)\\n" "$svc_name" "$service" "$status" "$enabled"\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${CYAN}==========================================${NC}"\r\n    echo ""\r\n}\r\n\r\n# Start services function\r\nstart_services() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${GREEN}=========================================="\r\n    echo -e "       Starting Services"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${services[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        echo -en "${BLUE}[${svc_name}]${NC} Starting ${service}... "\r\n        \r\n        if systemctl start "$service" 2>/dev/null; then\r\n            echo -e "${GREEN}✓ Success${NC}"\r\n        else\r\n            echo -e "${RED}✗ Failed${NC}"\r\n        fi\r\n        sleep 0.5\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${GREEN}Services started successfully!${NC}"\r\n    check_status "${services[@]}"\r\n}\r\n\r\n# Stop services function\r\nstop_services() {\r\n    local services=("$@")\r\n    local reversed=()\r\n    \r\n    # Reverse array order (considering dependencies)\r\n    for ((i=${#services[@]}-1; i>=0; i--)); do\r\n        reversed+=("${services[i]}")\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${RED}=========================================="\r\n    echo -e "       Stopping Services"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${reversed[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        echo -en "${BLUE}[${svc_name}]${NC} Stopping ${service}... "\r\n        \r\n        if systemctl stop "$service" 2>/dev/null; then\r\n            echo -e "${GREEN}✓ Success${NC}"\r\n        else\r\n            echo -e "${YELLOW}⚠ Failed (already stopped or error)${NC}"\r\n        fi\r\n        sleep 0.5\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${RED}Services stopped successfully!${NC}"\r\n    check_status "${services[@]}"\r\n}\r\n\r\n# Restart services function\r\nrestart_services() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${YELLOW}=========================================="\r\n    echo -e "       Restarting Services"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    stop_services "${services[@]}"\r\n    sleep 2\r\n    start_services "${services[@]}"\r\n}\r\n\r\n# Enable services function\r\nenable_services() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${GREEN}=========================================="\r\n    echo -e "       Enabling Services"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${services[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        echo -en "${BLUE}[${svc_name}]${NC} Enabling ${service}... "\r\n        \r\n        if systemctl enable "$service" 2>/dev/null; then\r\n            echo -e "${GREEN}✓ Success${NC}"\r\n        else\r\n            echo -e "${RED}✗ Failed${NC}"\r\n        fi\r\n        sleep 0.3\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${GREEN}Services enabled successfully!${NC}"\r\n    check_status "${services[@]}"\r\n}\r\n\r\n# Disable services function\r\ndisable_services() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${YELLOW}=========================================="\r\n    echo -e "       Disabling Services"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${services[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        echo -en "${BLUE}[${svc_name}]${NC} Disabling ${service}... "\r\n        \r\n        if systemctl disable "$service" 2>/dev/null; then\r\n            echo -e "${GREEN}✓ Success${NC}"\r\n        else\r\n            echo -e "${RED}✗ Failed${NC}"\r\n        fi\r\n        sleep 0.3\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${YELLOW}Services disabled successfully!${NC}"\r\n    check_status "${services[@]}"\r\n}\r\n\r\n# Reload systemd daemon function\r\nreload_daemon() {\r\n    echo ""\r\n    echo -e "${CYAN}=========================================="\r\n    echo -e "       Reloading Systemd Daemon"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    echo -en "${BLUE}Executing systemctl daemon-reload...${NC} "\r\n    \r\n    if systemctl daemon-reload 2>/dev/null; then\r\n        echo -e "${GREEN}✓ Success${NC}"\r\n        echo ""\r\n        echo -e "${GREEN}Systemd daemon reloaded successfully!${NC}"\r\n    else\r\n        echo -e "${RED}✗ Failed${NC}"\r\n        echo ""\r\n        echo -e "${RED}Failed to reload systemd daemon!${NC}"\r\n        exit 1\r\n    fi\r\n    \r\n    echo ""\r\n}\r\n\r\n# View log file function\r\nview_log() {\r\n    local log_target="$1"\r\n    local log_file=""\r\n    \r\n    case "$log_target" in\r\n        web)\r\n            log_file="$WEB_LOG"\r\n            ;;\r\n        ctrl)\r\n            log_file="$CTRL_LOG"\r\n            ;;\r\n        *)\r\n            echo ""\r\n            echo -e "${RED}Error: Unknown log target '$log_target'${NC}"\r\n            echo -e "${YELLOW}Available log targets: web, ctrl${NC}"\r\n            echo ""\r\n            exit 1\r\n            ;;\r\n    esac\r\n    \r\n    if [ ! -f "$log_file" ]; then\r\n        echo ""\r\n        echo -e "${RED}Error: Log file not found: $log_file${NC}"\r\n        echo ""\r\n        exit 1\r\n    fi\r\n    \r\n    echo ""\r\n    echo -e "${CYAN}=========================================="\r\n    echo -e "       Viewing Log: $log_file"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    echo -e "${YELLOW}Press Ctrl+C to exit${NC}"\r\n    echo ""\r\n    \r\n    tail -200f "$log_file"\r\n}\r\n\r\n# Get target services function\r\nget_target_services() {\r\n    local target="$1"\r\n    \r\n    case "$target" in\r\n        all)\r\n            echo "${ALL_SERVICES[@]}"\r\n            ;;\r\n        service)\r\n            echo "${WEB_SERVICES[@]}"\r\n            ;;\r\n        db)\r\n            echo "${DB_SERVICES[@]}"\r\n            ;;\r\n        nginx|rpc|api|check|redis|mariadb)\r\n            echo "$target"\r\n            ;;\r\n        *)\r\n            echo ""\r\n            return 1\r\n            ;;\r\n    esac\r\n    return 0\r\n}\r\n\r\n# Check arguments\r\nif [ $# -eq 0 ]; then\r\n    show_usage\r\n    exit 1\r\nfi\r\n\r\n# Handle help option (can be first or second argument)\r\nif [ "$1" == "help" ] || [ "$1" == "--help" ] || [ "$1" == "-h" ] || [ "$2" == "help" ] || [ "$2" == "--help" ] || [ "$2" == "-h" ]; then\r\n    show_usage\r\n    exit 0\r\nfi\r\n\r\n# Handle reload action (doesn't require target)\r\nif [ "$1" == "reload" ]; then\r\n    reload_daemon\r\n    exit 0\r\nfi\r\n\r\n# Handle log action (requires log target)\r\nif [ "$1" == "log" ]; then\r\n    if [ $# -lt 2 ]; then\r\n        echo ""\r\n        echo -e "${RED}Error: Log target must be specified.${NC}"\r\n        echo -e "${YELLOW}Available log targets: web, ctrl${NC}"\r\n        echo ""\r\n        exit 1\r\n    fi\r\n    view_log "$2"\r\n    exit 0\r\nfi\r\n\r\nif [ $# -lt 2 ]; then\r\n    echo ""\r\n    echo -e "${RED}Error: Both action and target must be specified.${NC}"\r\n    show_usage\r\n    exit 1\r\nfi\r\n\r\nACTION="$1"\r\nTARGET="$2"\r\n\r\n# Get target services\r\nTARGET_SERVICES=($(get_target_services "$TARGET"))\r\n\r\nif [ ${#TARGET_SERVICES[@]} -eq 0 ]; then\r\n    echo ""\r\n    echo -e "${RED}Error: Unknown target '$TARGET'${NC}"\r\n    show_usage\r\n    exit 1\r\nfi\r\n\r\n# Process action\r\ncase "$ACTION" in\r\n    status)\r\n        check_status "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    start)\r\n        start_services "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    stop)\r\n        stop_services "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    restart)\r\n        restart_services "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    enable)\r\n        enable_services "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    disable)\r\n        disable_services "${TARGET_SERVICES[@]}"\r\n        ;;\r\n    *)\r\n        echo ""\r\n        echo -e "${RED}Error: Unknown action '$ACTION'${NC}"\r\n        show_usage\r\n        exit 1\r\n        ;;\r\nesac\r\n\r\nexit 0\n```\n\n\\\n\\\n	2026-02-27 01:33:20.637+00	2026-02-27 01:33:20.679+00	97bb95f8-3ffa-44aa-b51b-dfd5430f3524	349f6272-94d8-453f-b753-b885293e6cc8	12.0.0	2	\N
