art services"\r\n    echo "  stop      - Stop services"\r\n    echo "  restart   - Restart services"\r\n    echo "  status    - Check service status"\r\n    echo "  enable    - Enable services (auto-start on boot)"\r\n    echo "  disable   - Disable services (no auto-start)"\r\n    echo "  reload    - Reload systemd daemon"\r\n    echo "  log       - View log files (tail -200f)"\r\n    echo ""\r\n    echo "Targets:"\r\n    echo "  all       - All services"\r\n    echo "  util      - Utility services (rsyslog, cron)"\r\n    echo "  redis     - Redis service"\r\n    echo "  web       - Web services (gateway-check, gateway, nginx)"\r\n    echo "  vpn       - VPN services (vpn, strongswan)"\r\n    echo "  dhcp      - DHCP services (dhcp, dhcp6)"\r\n    echo "  kernel    - Kernel module services (syn-driver, syn-gateway)"\r\n    echo ""\r\n    echo "Log Targets:"\r\n    echo "  gw        - Gateway log (/var/connect/logs/connect-gw.log)"\r\n    echo "  vpn       - VPN log (/var/connect/connect-vpn/log/connect-vpn.log)"\r\n    echo ""\r\n    echo "Individual services:"\r\n    echo "  rsyslog       - Rsyslog"\r\n    echo "  cron          - Cron"\r\n    echo "  gateway-check - Gateway Check service"\r\n    echo "  gateway       - Gateway service"\r\n    echo "  nginx         - Nginx"\r\n    echo "  vpn           - VPN service"\r\n    echo "  strongswan    - StrongSwan"\r\n    echo "  dhcp          - DHCP server (IPv4)"\r\n    echo "  dhcp6         - DHCP server (IPv6)"\r\n    echo "  syn-driver    - SYN Driver"\r\n    echo "  syn-gateway   - SYN Gateway"\r\n    echo ""\r\n    echo "Examples:"\r\n    echo "  sudo $0 status all          # Check all services status"\r\n    echo "  sudo $0 start web           # Start web services"\r\n    echo "  sudo $0 stop vpn            # Stop VPN services"\r\n    echo "  sudo $0 restart nginx       # Restart Nginx"\r\n    echo "  sudo $0 start dhcp          # Start DHCP services"\r\n    echo "  sudo $0 enable web          # Enable web services auto-start"\r\n    echo "  sudo $0 disable vpn         # Disable VPN services auto-start"\r\n    echo "  sudo $0 reload              # Reload systemd daemon"\r\n    echo "  sudo $0 log gw              # View gateway log"\r\n    echo "  sudo $0 log vpn             # View VPN log"\r\n    echo ""\r\n    echo -e "${CYAN}==========================================${NC}"\r\n    echo ""\r\n}\r\n\r\n# Check service status function\r\ncheck_status() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${CYAN}=========================================="\r\n    echo -e "       Service Status Check"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${services[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        if systemctl is-active --quiet "$service"; then\r\n            status="${GREEN}●${NC} active (running)"\r\n        else\r\n            status="${RED}●${NC} inactive (dead)"\r\n        fi\r\n        \r\n        if systemctl is-enabled --quiet "$service" 2>/dev/null; then\r\n            enabled="${GREEN}enabled${NC}"\r\n        else\r\n            enabled="${YELLOW}disabled${NC}"\r\n        fi\r\n        \r\n        printf "${BLUE}[%-13s]${NC} %-35s %b (%b)\\n" "$svc_name" "$service" "$status" "$enabled"\r\n    done\r\n    \r\n    echo ""\r\n    echo -e "${CYAN}==========================================${NC}"\r\n    echo ""\r\n}\r\n\r\n# Start services function\r\nstart_services() {\r\n    local services=("$@")\r\n    \r\n    echo ""\r\n    echo -e "${GREEN}=========================================="\r\n    echo -e "       Starting Services"\r\n    echo -e "==========================================${NC}"\r\n    echo ""\r\n    \r\n    for svc_name in "${services[@]}"; do\r\n        service="${SERVICE_MAP[$svc_name]}"\r\n        \r\n        echo -en "${BLUE}[${svc_name}]${NC} Starting ${service}... "\r\n        \r\n        if systemctl start "$service" 2>/dev/null; then